import { fromGlobalTouchClick } from './fromGlobalTouchClick';
import { filter } from 'rxjs/operators';
export function fromOutsideTouchClick(element) {
  return fromGlobalTouchClick().pipe(filter(event => {
    let node = event.target || null;

    while (node) {
      if (node === element) {
        break;
      }

      node = node.parentElement;
    }

    return node === null;
  }));
}
